query.base:
TS metrics-gcp.compute.otel-*
// Managed instance groups only (resource-level dimensions; no attributes.* labels on this metric)
| WHERE resource.attributes.gcp.resource_type == "instance_group"
// instance_group/size is a GAUGE: number of VMs currently in the group.
// OTel TSDS can split one entity's history into several series (_metric_names_hash is a dimension).
// Collapse to one row per minute first, then: means = SUM(sums) / SUM(counts); latest value = LAST(x, minute).
| STATS size = MAX(MAX_OVER_TIME(`compute.googleapis.com/instance_group/size`))
  BY minute = TBUCKET(1 minute), resource.attributes.project_id, resource.attributes.location, resource.attributes.instance_group_name
// Peak size in the window vs the most recent size (latest minute by timestamp, not the max of each series' last value)
| STATS
    max_size = MAX(size),
    current_size = LAST(size, minute) WHERE size IS NOT NULL
  BY resource.attributes.project_id, resource.attributes.location, resource.attributes.instance_group_name
